    private void initFeaturedProduct() {
        rvProduct = rootView.findViewById(R.id.rvFeaturedProduct);
        int mNoOfColumns = RecyclerViewUtils.calculateNoOfColumns(context, 100);
        RecyclerView.LayoutManager layoutManager = new GridLayoutManager(context,mNoOfColumns);
        rvProduct.setNestedScrollingEnabled(false);
        rvProduct.setLayoutManager(layoutManager);

        final ProductFeaturedAdapter adapter = new ProductFeaturedAdapter(context);
        rvProduct.setAdapter(adapter);

        viewModel.GetAll().observe(activity, new Observer<List<ProductFeatured>>() {
            @Override
            public void onChanged(@Nullable List<ProductFeatured> productFeatureds) {
                adapter.setDatas(productFeatureds);
            }
        });
        adapter.setOnClickListener(new ProductFeaturedAdapter.OnItemClickListener() {
            @Override
            public void onItemClick(ProductFeatured model) {
                ProductViewFragment fragment = new ProductViewFragment();
//                Bundle args = new Bundle();
//                args.putInt("id", product.getId());
//                fragment.setArguments(args);
                getFragmentManager().beginTransaction().
                        replace(R.id.content, fragment).
                        addToBackStack(null).
                        commit();
            }
        });
    }

